<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class MethodicalActivityController extends Controller{
private function manage(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('methodical_head')||$r->user()->canDo('methodical.manage'),403);}
public function meetings(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('methodical_meetings as m')->leftJoin('methodical_commissions as c','c.id','=','m.methodical_commission_id')->where('m.academic_period_id',$p->id)->select('m.*','c.name as commission_name')->orderByDesc('m.held_at')->get();$commissions=DB::table('methodical_commissions')->where('active',1)->get();return view('methodical.meetings',compact('rows','commissions'));}
public function meetingStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['methodical_commission_id'=>'nullable|exists:methodical_commissions,id','type'=>'required|in:commission,methodical_council,seminar','held_at'=>'required|date','number'=>'nullable|string|max:100','title'=>'required|string|max:500','agenda'=>'nullable|string|max:10000']);DB::table('methodical_meetings')->insert($d+['academic_period_id'=>$p->id,'status'=>'planned','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
public function development(Request $r){$this->manage($r);$rows=DB::table('teacher_development_records as d')->join('teachers as t','t.id','=','d.teacher_id')->select('d.*','t.last_name as full_name')->orderByDesc('d.ends_on')->get();$teachers=DB::table('teachers')->orderBy('last_name')->get();return view('methodical.development',compact('rows','teachers'));}
public function developmentStore(Request $r){$this->manage($r);$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','type'=>'required|in:qualification,internship,certification,seminar,competition,publication','title'=>'required|string|max:500','organization'=>'nullable|string|max:500','starts_on'=>'nullable|date','ends_on'=>'nullable|date','hours'=>'nullable|numeric|min:0','document_number'=>'nullable|string|max:100','document_date'=>'nullable|date','next_due_on'=>'nullable|date']);DB::table('teacher_development_records')->insert($d+['created_at'=>now(),'updated_at'=>now()]);return back();}
public function observations(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$rows=DB::table('lesson_observations as o')->join('teachers as t','t.id','=','o.teacher_id')->leftJoin('teachers as v','v.id','=','o.observer_teacher_id')->where('o.academic_period_id',$p->id)->select('o.*','t.last_name as teacher_name','v.last_name as observer_name')->orderByDesc('o.observed_on')->get();$teachers=DB::table('teachers')->orderBy('last_name')->get();return view('methodical.observations',compact('rows','teachers'));}
public function observationStore(Request $r){$this->manage($r);$p=$r->attributes->get('academic_period');$d=$r->validate(['teacher_id'=>'required|exists:teachers,id','observer_teacher_id'=>'nullable|exists:teachers,id','observed_on'=>'required|date','subject'=>'nullable|string|max:500','group_name'=>'nullable|string|max:100','type'=>'required|in:mutual,open,control','strengths'=>'nullable|string|max:10000','recommendations'=>'nullable|string|max:10000','result'=>'nullable|string|max:500']);DB::table('lesson_observations')->insert($d+['academic_period_id'=>$p->id,'created_at'=>now(),'updated_at'=>now()]);return back();}
}